# app/logic/scheme_index.R
#
# Where typing schemes for a species are published. The index ships with the
# app (data/scheme_index.csv, generated by dev/scheme_index/) and holds only
# scheme names, locus counts and the provider's download page - no alleles,
# profiles or locus tables. PhyloTrace never contacts a provider: it points the
# user to the page, the user downloads the files under the provider's terms and
# imports them.

box::use(
  utils[read.csv],
)

box::use(
  app / logic / species[species_parts],
)

#' Scheme Types Offered as a Core Genome Scheme
#'
#' @description Types the cgMLST step offers: a wgMLST schema is a locus set
#'   like any other to pyMLST, only larger.
#' @export
CORE_TYPES <- c("cgMLST", "wgMLST")

# Order in which scheme types are listed.
TYPE_ORDER <- c("cgMLST", "wgMLST", "MLST")

# Lazily loaded index.
.cache <- new.env(parent = emptyenv())

#' Scheme Index
#'
#' @description One row per published scheme: `species` (as stored for a
#'   database; `Genus spp` for a genus-wide scheme), `type` (`cgMLST`,
#'   `wgMLST` or `MLST`), `provider` (id of `scheme_sources`), `scheme`, `loci` (integer,
#'   `NA` when not recorded), `url` (the provider's page for the scheme), `note`
#'   and `source_id` (the scheme's id at the provider, e.g.
#'   `pubmlst_listeria_seqdef/3`; used by `scheme_guide` to build download
#'   commands).
#'
#' @return Data frame.
#' @export
scheme_index <- function() {
  if (is.null(.cache$index)) {
    # box::file() resolves against this module's directory, so the table also
    # loads when the working directory is not the app root (testthat).
    index <- read.csv(
      box::file("data", "scheme_index.csv"),
      colClasses = "character",
      na.strings = ""
    )
    index$loci <- suppressWarnings(as.integer(index$loci))
    .cache$index <- index
  }
  .cache$index
}

# TRUE where an index species covers the given genus and epithets: same genus,
# and either side genus-wide or the two sharing an epithet.
covers <- function(index_species, genus, epithets) {
  vapply(
    index_species,
    function(s) {
      parts <- species_parts(s)
      same_genus <- !is.na(parts$genus) && identical(tolower(parts$genus), tolower(genus))
      same_genus && (
        !length(parts$epithets) ||
          !length(epithets) ||
          any(tolower(parts$epithets) %in% tolower(epithets))
      )
    },
    logical(1),
    USE.NAMES = FALSE
  )
}

#' Published Schemes for a Species
#'
#' @description Matches a species or species group against the index. A group
#'   finds every scheme naming one of its species, and genus-wide schemes
#'   (`Salmonella spp`) are found for every species of the genus.
#'
#' @param species Character species name, e.g. `"Klebsiella pneumoniae"`.
#' @param type Character scheme types to keep (`"cgMLST"`, `"wgMLST"`,
#'   `"MLST"`), or `NULL` for all.
#'
#' @return Rows of `scheme_index()`: cgMLST, wgMLST, then MLST, each by provider.
#' @export
schemes_for_species <- function(species, type = NULL) {
  index <- scheme_index()
  if (is.null(species) || length(species) != 1L || is.na(species) || !nzchar(species)) {
    return(index[0, , drop = FALSE])
  }
  parts <- species_parts(species)
  if (is.na(parts$genus)) {
    return(index[0, , drop = FALSE])
  }
  hits <- index[covers(index$species, parts$genus, parts$epithets), , drop = FALSE]
  if (!is.null(type)) {
    hits <- hits[hits$type %in% type, , drop = FALSE]
  }
  hits <- hits[order(match(hits$type, TYPE_ORDER), hits$provider, hits$scheme), , drop = FALSE]
  rownames(hits) <- NULL
  hits
}
